// Palabras que nos interesan (sin tildes, en minúsculas). Añade o quita las que quieras.
const palabras = [
  'riego', 'regadio', 'regantes', 'bombeo', 'fotovolta', 'solar',
  'renovable', 'autoconsumo', 'eficiencia energetica', 'modernizacion de regadios',
  'explotaciones agrarias', 'pozo', 'agua para riego'
];
// Solo lo publicado en las últimas N horas (así no se repiten avisos cada día).
const horas = 26;

const limpiar = (t) => (t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const desde = Date.now() - horas * 3600 * 1000;

return $input.all()
  .filter((item) => {
    const j = item.json;
    const fecha = Date.parse(j.isoDate || j.pubDate || '');
    if (!Number.isNaN(fecha) && fecha < desde) return false;
    const texto = limpiar(`${j.title} ${j.contentSnippet || j.content || ''}`);
    return palabras.some((p) => texto.includes(p));
  })
  .map((item) => {
    const j = item.json;
    const texto = limpiar(`${j.title} ${j.contentSnippet || j.content || ''}`);
    return {
      json: {
        titulo: j.title,
        enlace: j.link,
        fecha: j.isoDate || j.pubDate,
        coincide: palabras.filter((p) => texto.includes(p)).join(', '),
        texto: String(j.contentSnippet || j.content || '').slice(0, 4000),
      },
    };
  });

// Junta todos los anuncios en UN solo aviso, con el resumen de Gemini.
// Saca dos versiones: "telegram" (texto) y "html" (email). Si Gemini falla, el anuncio sale igual, sin resumen.
const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const anuncios = $('Preparar petición a Gemini').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);
const resumenDe = (k) => (respuestas[k] || {}).candidates?.[0]?.content?.parts?.map((p) => p.text).join('').trim();

const asunto = `BOJA: ${anuncios.length} anuncio${anuncios.length === 1 ? '' : 's'} de riego / solar`;

// --- Telegram (formato HTML de Telegram: solo <b>, <i>, <a>) ---
let telegram = `<b>${esc(asunto)}</b>\n`;
anuncios.forEach((a, k) => {
  const r = resumenDe(k);
  const bloque = `\n<b>${esc(a.titulo)}</b>\n${r ? esc(r) : '<i>(Sin resumen: Gemini no respondió)</i>'}\n<a href="${esc(a.enlace)}">Ver en el BOJA</a>\n`;
  if ((telegram + bloque).length < 3900) telegram += bloque; // Telegram admite hasta 4096 caracteres
});
telegram += '\n<i>Resúmenes hechos por IA: revísalos antes de usarlos.</i>';

// --- Email (por si algún día se vuelve a activar) ---
const lista = anuncios.map((a, k) => {
  const r = resumenDe(k);
  return `
  <li style="margin-bottom:18px">
    <a href="${esc(a.enlace)}"><strong>${esc(a.titulo)}</strong></a><br>
    ${r ? `<span>${esc(r)}</span><br>` : '<em style="color:#a00">(Sin resumen: Gemini no respondió)</em><br>'}
    <small style="color:#666">${esc((a.fecha || '').slice(0, 10))} · coincide: ${esc(a.coincide)}</small>
  </li>`;
}).join('');
const html = `<p>Hoy el BOJA trae esto que puede interesarnos:</p><ul>${lista}</ul>
<p style="color:#666;font-size:12px">Resúmenes hechos por IA (Gemini): revísalos antes de usarlos. Aviso automático del vigilante del BOJA (n8n).</p>`;

return [{ json: { asunto, telegram, html } }];

// Instrucciones para Gemini. Cámbialas si quieres otro estilo de resumen.
const instrucciones = `Eres redactor de una instaladora de bombeo solar para riego en Andalucía.
Resume este anuncio del BOJA en 2 o 3 frases sencillas para un agricultor o una comunidad de regantes:
de qué trata, a quién va dirigido y el plazo SOLO si aparece en el texto.
Reglas:
- No inventes nada que no esté en el texto.
- No pongas importes ni cantidades de dinero.
- Nunca prometas que alguien conseguirá la ayuda.
- Si el texto no da para saber de qué trata, dilo en una frase.
- Termina con: "Consulta los requisitos en la convocatoria oficial."
- Solo el resumen, sin títulos ni viñetas.`;

return $input.all().map((item) => ({
  json: {
    ...item.json,
    peticion: {
      contents: [{ parts: [{ text: `${instrucciones}\n\nTÍTULO: ${item.json.titulo}\n\nTEXTO: ${item.json.texto || '(sin texto)'}` }] }],
      generationConfig: { temperature: 0.2 },
    },
  },
}));

// Una noticia por anuncio, con el resumen de Gemini (si Gemini falló, va sin resumen: se escribe en el panel).
// La web la guarda como BORRADOR: no se ve nada hasta publicarla desde el panel (/admin.html → Noticias).
const anuncios = $('Preparar petición a Gemini').all().map((i) => i.json);
const respuestas = $input.all().map((i) => i.json);
const resumenDe = (k) => (respuestas[k] || {}).candidates?.[0]?.content?.parts?.map((p) => p.text).join('').trim() || '';

return anuncios.map((a, k) => ({
  json: {
    titulo: a.titulo,
    enlace: a.enlace,
    fecha: a.fecha,
    resumen: resumenDe(k),
    coincide: a.coincide,
    fuente: 'BOJA',
  },
}));
